cd ~/workspace && echo '' | base64 -d | gunzip > /tmp/RelatorioVendas.tsx && node -e '
const fs=require("fs"),crypto=require("crypto"),h=f=>crypto.createHash("sha256").update(fs.readFileSync(f)).digest("hex").slice(0,16);
if(h("/tmp/RelatorioVendas.tsx")!=="ff348766e0f9b5d9"){console.log("❌ O comando chegou cortado. Copie de novo o bloco inteiro.");process.exit(1);}
const A="artifacts/fechamento/src/pages/RelatorioVendas.tsx";
if(!fs.existsSync(A)){console.log("❌ Não achei a aba Relatórios. Nada foi alterado.");process.exit(1);}
if(!fs.readFileSync(A,"utf8").includes("INICIO_MP")&&!fs.existsSync(A+".antes-unificado"))fs.copyFileSync(A,A+".antes-unificado");
fs.copyFileSync("/tmp/RelatorioVendas.tsx",A);
console.log("✓ Aba Relatórios unificada instalada (a anterior ficou em RelatorioVendas.tsx.antes-unificado)");
console.log("\n✅ PRONTO. Recarregue a pré-visualização e abra Relatórios.");
'
